'use client';

/**
 * @file SpinnerOwnerContext.ts
 * @input React
 * @output SpinnerOwnerContext: true inside a Core component that owns the
 *   task a composed Spinner shows, so that Spinner announces nothing
 * @position Internal to core: not exported from Spinner/index.ts, and core's
 *   `exports` do not list this module. The owner of a task announces it, so
 *   a Spinner it composes stays silent; app code hides a composed Spinner
 *   with `aria-hidden` instead.
 *
 * SYNC: When modified, update:
 * - /packages/core/src/Spinner/Spinner.tsx
 */

import {createSharedContext} from '../utils/sharedContext';

export const SpinnerOwnerContext = createSharedContext(
  'SpinnerOwnerContext',
  1,
  false,
);
SpinnerOwnerContext.displayName = 'SpinnerOwnerContext';

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file index.ts
 * @input Imports from Spinner component
 * @output Exports Spinner component and related types
 * @position Entry point for Spinner; re-exported by /packages/core/src/index.ts
 *
 * SYNC: When modified, update this header and /packages/core/src/Spinner/Spinner.doc.mjs
 */

export {Spinner} from './Spinner';
export type {SpinnerProps, SpinnerSize, SpinnerShade} from './Spinner';

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file spinnerRotor.ts
 * @input StyleX keyframes and the slow-min duration token
 * @output The one turning arc: SPINNER_ARC_FRACTION, spinnerRotorStyles.turn
 *   and syncRotationPhase
 * @position Spinner's rotor, shared by Spinner and Lab's indeterminate
 *   CircularProgress (through `@astryxdesign/core/internal/spinner-rotor`), so
 *   both rings turn the same way on the compositor.
 */

import * as stylex from '@stylexjs/stylex';
